<template>
  <view class="container">
    <!-- 顶部区域 -->
    <view class="header">
      <!-- 搜索框 -->
      <view class="search-box">
        <image class="search-icon" src="/static/sous.png"></image>
        <input
          class="search-input"
          placeholder="搜索医院、科室或疾病"
          v-model="searchKeyword"
          @confirm="handleSearch"
          confirm-type="search"
        />
      </view>
    </view>

    <!-- 轮播图 -->
    <view class="banner-section">
      <swiper class="banner-swiper" indicator-dots="true" autoplay="true" interval="3000" duration="500">
        <swiper-item>
          <view class="banner-item">
            <image class="banner-bg" src="/static/banner.jpg"></image>
            <view class="banner-content">
              <text class="banner-title">专业医疗陪诊服务</text>
              <text class="banner-subtitle">让您的医疗就诊更加便捷</text>
              <view class="banner-btn" @click="navigateToAppointmentForm">
                <text class="btn-text">立即预约陪诊</text>
              </view>
            </view>
          </view>
        </swiper-item>
      </swiper>
    </view>

    <!-- 服务分类 -->
    <view class="category-section">
      <view class="category-grid">
        <view
          class="category-item"
          v-for="(item, index) in categories"
          :key="index"
          @click="navigateToCategory(item)"
        >
          <image class="category-icon" :src="item.icon"></image>
          <text class="category-text">{{ item.name }}</text>
        </view>
      </view>
    </view>

    <!-- 服务流程 -->
    <view class="service-section">
      <view class="section-title">
        <text class="title-text">服务流程</text>
      </view>
      <view class="service-grid">
        <view class="service-item" v-for="(item, index) in services" :key="index">
          <image class="service-icon" :src="item.icon"></image>
          <text class="service-text">{{ item.name }}</text>
        </view>
      </view>
    </view>

    <!-- 推荐陪诊员 -->
    <view class="companion-section">
      <view class="section-header">
        <text class="section-title">推荐陪诊员</text>
      </view>
      <scroll-view class="companion-scroll" scroll-x="true" show-scrollbar="true">
        <view class="companion-list">
          <view
            class="companion-item"
            v-for="(companion, index) in companions"
            :key="index"
            @click="navigateToCompanion(companion)"
          >
            <image class="companion-avatar" :src="companion.avatar"></image>
            <view class="companion-info">
              <text class="companion-name">{{ companion.name }}</text>
              <text class="companion-specialty">{{ companion.specialty }}</text>
              <text class="companion-experience">{{ companion.experience }}</text>
              <view class="rating-section">
                <text class="rating">★ {{ companion.rating }}</text>
                <text class="service-count">已服务 {{ companion.serviceCount }} 人次</text>
              </view>
            </view>
          </view>
        </view>
      </scroll-view>
    </view>

    <!-- ========== 新增：可拖动悬浮按钮 ========== -->
    <view
      class="floating-btn"
      :style="{ left: btnLeft + 'px', top: btnTop + 'px' }"
      @touchstart="handleTouchStart"
      @touchmove="handleTouchMove"
      @touchend="isDragging = false"
      @mousedown="handleMouseDown"
      @mousemove="handleMouseMove"
      @mouseup="isDragging = false"
      @mouseleave="isDragging = false"
      @click.stop="navigateToAIaks"
    >
      <image class="floating-icon" src="/static/mynewlogo.png" mode="aspectFit" />
    </view>
  </view>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { getAllAttendants } from '../../api/attendant.js'

// 响应式数据
const searchKeyword = ref('')
const categories = ref([
  { name: '门诊陪诊', icon: '/static/category1.jpg' },
  { name: '住院陪护', icon: '/static/category2.jpg' },
  { name: '专家会诊', icon: '/static/category3.jpg' },
  { name: '检查陪同', icon: '/static/category4.jpg' }
])
const services = ref([
  { name: '预约服务', icon: '/static/yvyue_2.png' },
  { name: '匹配陪诊员', icon: '/static/ren_1.png' },
  { name: '专业陪诊', icon: '/static/xin.png' },
  { name: '评价反馈', icon: '/static/wujiaoxin.png' }
])
const companions = ref([])

// ========== 悬浮按钮位置状态 ==========
const btnLeft = ref(0) // 初始化为 0，将在 onMounted 中设置
const btnTop = ref(0)  // 初始化为 0，将在 onMounted 中设置
const isDragging = ref(false)
const startX = ref(0)
const startY = ref(0)
const startLeft = ref(0)
const startTop = ref(0)

// ========== 拖拽逻辑 ==========
const handleTouchStart = (e) => {
  const touch = e.touches[0]
  startX.value = touch.clientX
  startY.value = touch.clientY
  startLeft.value = btnLeft.value
  startTop.value = btnTop.value
  isDragging.value = true
}

const handleTouchMove = (e) => {
  if (!isDragging.value) return
  const touch = e.touches[0]
  const deltaX = touch.clientX - startX.value
  const deltaY = touch.clientY - startY.value
  updatePosition(startLeft.value + deltaX, startTop.value + deltaY)
}

const handleMouseDown = (e) => {
  startX.value = e.clientX
  startY.value = e.clientY
  startLeft.value = btnLeft.value
  startTop.value = btnTop.value
  isDragging.value = true
}

const handleMouseMove = (e) => {
  if (!isDragging.value) return
  const deltaX = e.clientX - startX.value
  const deltaY = e.clientY - startY.value
  updatePosition(startLeft.value + deltaX, startTop.value + deltaY)
}

const updatePosition = (x, y) => {
  // 获取窗口尺寸（兼容 uni-app）
  const sysInfo = uni.getSystemInfoSync()
  const windowWidth = sysInfo.windowWidth
  const windowHeight = sysInfo.windowHeight

  // 转换 rpx 到 px 的比例（uni-app 中 1rpx = windowWidth / 750 px）
  const rpxToPx = windowWidth / 750
  const btnSizePx = 60 * rpxToPx // 按钮宽高 60rpx

  // 边界限制：不让按钮移出屏幕
  x = Math.max(0, Math.min(windowWidth - btnSizePx, x))
  y = Math.max(0, Math.min(windowHeight - btnSizePx, y))

  btnLeft.value = x
  btnTop.value = y
}

const setInitialPosition = () => {
  const sysInfo = uni.getSystemInfoSync()
  const windowWidth = sysInfo.windowWidth
  const windowHeight = sysInfo.windowHeight // 这是可视窗口高度（不含 TabBar）

  // 转换 rpx 到 px 的比例
  const rpxToPx = windowWidth / 750
  const btnSizePx = 60 * rpxToPx // 按钮宽高 60rpx

  // 计算右下角位置（X 和 Y）
  // X: 屏幕宽度 - 按钮宽度
  const initialLeft = windowWidth - btnSizePx

  // Y: 可视窗口高度 - 按钮高度（确保按钮在 TabBar 上方）
  const initialTop = windowHeight - btnSizePx

  // 设置初始位置
  btnLeft.value = initialLeft
  btnTop.value = initialTop
}
// ========== 跳转方法 ==========
const navigateToAIaks = () => {
  uni.navigateTo({
    url: '/pages/AIaks/AIaks'
  })
}

const navigateToAppointmentForm = () => {
  uni.navigateTo({
    url: '/pages/AItriage/01_AppointmentSelection'
  })
}

const navigateToCategory = (category) => {
  console.log('点击分类:', category.name)
  uni.switchTab({ url: '/pages/appointment/appointment' })
}

const navigateToCompanion = (companion) => {
  console.log('点击陪诊员:', companion.name, '陪诊员ID:', companion.id)
  uni.showToast({ title: '陪诊师详情功能暂未开放', icon: 'none' })
}

const handleSearch = () => {
  if (searchKeyword.value.trim()) {
    console.log('搜索关键词:', searchKeyword.value)
    uni.showToast({ title: `搜索"${searchKeyword.value}"`, icon: 'none' })
  } else {
    uni.showToast({ title: '请输入搜索内容', icon: 'none' })
  }
}

const navigateToAppointment = () => {
  console.log('点击预约按钮')
  uni.switchTab({ url: '/pagesAItriage/01_AppointmentSelection' })
}

// 获取陪诊师列表
const fetchAttendants = async () => {
  try {
    const res = await getAllAttendants()
    console.log('陪诊师列表:', res)
    if (res.code === 200 && res.data) {
      companions.value = res.data.map((item) => ({
        id: item.id,
        name: item.name || '陪诊师' + item.id,
        specialty: item.certificate || '专业陪诊',
        experience: item.introduction || '专业陪诊服务',
        rating: 4.8,
        serviceCount: 100,
        avatar: '/static/provider' + ((item.id % 2) + 1) + '.jpg'
      }))
    } else {
      uni.showToast({ title: '获取陪诊师列表失败', icon: 'none' })
    }
  } catch (error) {
    console.error('获取陪诊师列表出错:', error)
    uni.showToast({ title: '网络错误，请稍后重试', icon: 'none' })
  }
}

// 页面挂载后执行
onMounted(() => {
  // 先设置初始位置到右下角
  setInitialPosition()
  // 再获取陪诊师列表
  fetchAttendants()
})
</script>

